def dedupe_count(items):
    seen = []
    checks = 0
    out = []
    for x in items:
        found = False
        for s in seen:
            checks += 1
            if s == x:
                found = True
                break
        if not found:
            seen.append(x)
            out.append(x)
    return out, checks
