import bisect
data = list(range(0, 2000, 2))
def linear_count(target):
    c = 0
    for x in data:
        c += 1
        if x == target:
            return c
    return c
def bisect_count(target):
    lo, hi = 0, len(data)
    c = 0
    while lo < hi:
        c += 1
        mid = (lo + hi) // 2
        if data[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return c
