def qs_count(a):
    if len(a) <= 1:
        return a, 0
    pivot = a[0]
    less = [x for x in a[1:] if x <= pivot]
    more = [x for x in a[1:] if x > pivot]
    ls, lc = qs_count(less)
    ms, mc = qs_count(more)
    return ls + [pivot] + ms, lc + mc + len(a) - 1
def depth(a):
